    23	  test('renders nothing for an empty name', () => {
    24	    const { container } = render(<ZimmProductName name="" as="h2" />);
    25	
    26	    // `name` is typed `string`, so TypeScript rules out an absent name but not an empty one. An
    27	    // empty `heading3` node is not free: it keeps its row in `ZimmProductContent`'s flex column
    28	    // and consumes the column's 20px `gap`, leaving a visible hole above the price.
    29	    //
    30	    // Asserted as an empty container rather than an absent testid, for the same reason
    31	    // `zimmProductPrice/index.test.tsx` does it: a node that still carried the recipe's styling
    32	    // but had lost its `data-testid` would satisfy the narrower check while being precisely the
    33	    // gap-consuming element this guard exists to prevent.
    34	    expect(container).toBeEmptyDOMElement();
    35	  });
    36	});
