     1	/**
     2	 * Scoped to this atom's own contract per testing.md: given a value or no value, does it render
     3	 * the right branch, does the label reach the DOM joined to the value as one readable line, and
     4	 * is that label *sourced* from `react-intl` rather than written into the component.
     5	 *
     6	 * The recipe's own resolution is covered by theme/components/recipeGuards.test.ts and
     7	 * ui-kits/recipeParts.test.ts; the visual result is covered by index.stories.tsx. Neither of
     8	 * those proves the absent-value branch is discoverable from this folder, which is what this is.
     9	 *
    10	 * Every render is wrapped: the atom calls `useIntl()`, which throws outside an `IntlProvider`
    11	 * (react-intl's `invariantIntlContext`). `.storybook/preview.tsx` supplies one for the stories;
    12	 * Vitest has no global provider, so it is supplied here.
    13	 */
    14	import React from 'react';
    15	import { describe, test, expect } from 'vitest';
    16	import { render, screen } from '@testing-library/react';
    17	import { IntlProvider } from 'react-intl';
    18	import { ZimmProductStyleCode } from './index';
    19	
    20	/** The id the component asks for. Repeated deliberately — see the sourcing test below. */
    21	const LABEL_ID = 'product_view.label.style_code';
    22	
    23	/**
    24	 * `locale` matches `defaultLocale` so react-intl treats an absent message as the ordinary
    25	 * fallback-to-`defaultMessage` path rather than a missing-translation error.
    26	 */
    27	const renderWithIntl = (ui: React.ReactElement, messages?: Record<string, string>) =>
    28	  render(
    29	    <IntlProvider locale="en-AU" defaultLocale="en-AU" messages={messages}>
    30	      {ui}
    31	    </IntlProvider>,
    32	  );
    33	
    34	describe('ZimmProductStyleCode', () => {
    35	  test('renders the label and value as one readable line', () => {
    36	    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />);
    37	    // The DS models label and value as two nodes; a screen reader and a copy-paste must still
    38	    // see the single string both composed page designs show. With no message supplied this is
    39	    // the `defaultMessage` path, which is what every locale renders until extraction runs.
    40	    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
    41	  });
    42	
    43	  test('takes the label from the intl provider rather than a literal in the component', () => {
    44	    // The guard against a regression to `const LABEL = 'Style Code:'`. A hardcoded English
    45	    // literal ships one language to all eleven locales, and it is invisible: the test above
    46	    // passes either way, because `defaultMessage` and the old literal are the same string.
    47	    // Supplying a different message for the same id is the only thing that tells them apart —
    48	    // an inlined literal cannot change, so this assertion can only pass if the label was looked
    49	    // up. The value must stay untouched, since it is a prop and not translatable copy.
    50	    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />, { [LABEL_ID]: 'Code de style :' });
    51	
    52	    expect(screen.getByTestId('product-style-code').textContent).toBe('Code de style : 8637DS241');
    53	  });
    54	
    55	  test.each([undefined, ''])('renders nothing for %s', (value) => {
    56	    renderWithIntl(<ZimmProductStyleCode value={value} />);
    57	    // The page places this unconditionally, so an absent style code must collapse rather than
    58	    // leave an empty styled node contributing to the stack's rhythm.
    59	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
    60	  });
    61	});
