    34	  parseRichText: (html?: string | null) => parseRichText(html),
    35	  isBlankRichText: (html?: string | null) => isBlankRichText(html),
    36	}));
    37	
    38	import { ZimmProductMeta } from './index';
    39	
    40	const MODEL_COPY = 'Model is 178cm and wears a size 0';
    41	const STYLE_CODE = '8637DS241';
    42	
    43	/**
    44	 * Every render is wrapped. This molecule renders `ZimmProductStyleCode`, which calls `useIntl()`
    45	 * above its own guard, and react-intl's `invariantIntlContext` throws outside a provider — so the
    46	 * wrapper is a precondition of rendering this molecule at all, not a per-test detail.
    47	 *
    48	 * Applied to all five renders, not only the three that pass a style code. The two all-absent cases
    49	 * happen to pass unwrapped today because the molecule's own guard returns before it reaches the
    50	 * atom — but that guard is precisely what those tests exist to check, so depending on it here
    51	 * would make the harness fail for the wrong reason the moment the guard regressed.
    52	 */
    53	const renderWithIntl = (ui: React.ReactElement) =>
    54	  render(
    55	    <IntlProvider locale="en-AU" defaultLocale="en-AU">
    56	      {ui}
    57	    </IntlProvider>,
    58	  );
