    61	  vi.clearAllMocks();
    62	  // Input-sensitive by design — see the file docstring. MODEL_COPY is the one value these tests
    63	  // treat as real rich text; everything else, including the `<p></p>` that Business Manager
    64	  // saves for an empty field, is blank.
    65	  isBlankRichText.mockImplementation((html?: string | null) => html !== MODEL_COPY);
    66	  parseRichText.mockImplementation((html?: string | null) => (html === MODEL_COPY ? [MODEL_COPY] : []));
