    69	describe('ZimmProductMeta', () => {
    70	  test('renders both rows, model line first, when the product has model copy and a style code', () => {
    71	    renderWithIntl(<ZimmProductMeta modelInfo={MODEL_COPY} styleCode={STYLE_CODE} />);
