    79	    // swapping the two children in index.tsx changes nothing measurable — the block still has
    80	    // two rows 28px apart, with the style code above the model line. Only order catches it.
    81	    expect(root.children[0]).toBe(screen.getByTestId('product-model-info'));
    82	    expect(root.children[1]).toBe(screen.getByTestId('product-style-code'));
    83	  });
    84	
