    86	    renderWithIntl(<ZimmProductMeta modelInfo={MODEL_COPY} />);
    87	
    88	    // The block must survive one absent row. A guard written with `||` instead of `&&` would
    89	    // drop the whole thing here, taking real model copy off the page — and so would a guard
    90	    // that tested `styleCode` where it should test `modelInfo`.
    91	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    92	    expect(screen.getByTestId('product-model-info')).toBeInTheDocument();
    93	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
    94	  });
    95	
    96	  test('renders the style code alone when there is no model copy', () => {
    97	    renderWithIntl(<ZimmProductMeta styleCode={STYLE_CODE} />);
    98	
    99	    // The common production shape: `c_modelFit` is unpopulated on most catalogue products, so
   100	    // this is the branch most shoppers see rather than an edge case.
   101	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
   102	    expect(screen.queryByTestId('product-model-info')).not.toBeInTheDocument();
   103	    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();
   104	  });
   105	
   106	  test.each([undefined, ''])('renders nothing at all when model copy is blank and styleCode is %s', (styleCode) => {
   107	    const { container } = renderWithIntl(<ZimmProductMeta modelInfo="<p></p>" styleCode={styleCode} />);
   108	
   109	    // Not "renders an empty div" — nothing. The wrapper's own `paddingTop` would otherwise be
   110	    // 28px of visible space with no content in it.
   111	    expect(container).toBeEmptyDOMElement();
   112	    expect(screen.queryByTestId('product-meta')).not.toBeInTheDocument();
   113	  });
   114	
   115	  test('resolves its recipe under a ChakraProvider — 28px of rhythm, not an inherited default', () => {
   116	    renderWithIntl(
   117	      <ChakraProvider theme={theme}>
   118	        <ZimmProductMeta modelInfo={MODEL_COPY} styleCode={STYLE_CODE} />
   119	      </ChakraProvider>,
   120	    );
   121	
   122	    // The only detection anywhere for this recipe losing its entry in theme/components/index.ts.
   123	    // An unregistered recipe makes `useMultiStyleConfig` return an empty object, `__css={undefined}`
   124	    // is a legal prop, and the block silently inherits — tsc, eslint and every other test in this
   125	    // file stay green. Asserting the resolved value rather than mere registration is strictly
   126	    // stronger: it also catches the recipe being registered carrying the wrong number.
   127	    //
   128	    // Measured as the declared token, not as `28px`. jsdom reports the literal CSS it was handed
   129	    // and does not resolve rem against the root font size — theme/index.test.tsx's own
   130	    // rendered-output tests record the same behaviour. index.stories.tsx's `play` measures the
   131	    // used px value in a real browser instead; the two are different measurements of the same
   132	    // declaration, not duplicates of each other.
   133	    const styles = window.getComputedStyle(screen.getByTestId('product-meta'));
