    20	 * the "would survive a refactor invisibly if broken" case .claude/rules/testing.md says to cover,
    21	 * so the corrected mechanism strengthens this guard's justification rather than weakening it.
    22	 *
    23	 * Comparing `parts` against the recipe's own `baseStyle` keys would not catch it: renaming a
    24	 * part in both places at once keeps them consistent with each other and still breaks the
    25	 * component. The component's reads are the only source of truth for what it needs, so this
    26	 * walks the component source.
    27	 *
    28	 * Scope: `overrides/app/components/**` — every co-located `<name>.css.ts`, which since the
    29	 * footer decomposition is where a component's recipe normally lives.
    30	 *
    31	 * It is not a whole-repo guard, and nothing else covers the remainder: the model is strictly
    32	 * sibling-based (a recipe's `parts` are reconciled against the `index.tsx` beside it), so a
    33	 * recipe that does not sit next to its component is out of reach. `theme/components/header.ts`
    34	 * is the only multipart recipe in that position today and is therefore unguarded.
    35	 * `theme/components/recipeGuards.test.ts` does not pick it up either — that suite has no
    36	 * parts-vs-reads check of any kind; it guards bare token keys and recipe namespacing.
    37	 *
    38	 * `READ_RE` recognises only the identifier `styles`, so a second binding in the same component
    39	 * is invisible here: `zimmSubscribeModal/index.tsx` reads `chrome.actions`. That one is
    40	 * deliberately out of scope rather than a gap to close — `chrome` holds *ZimmModal's* recipe,
    41	 * so the sibling model would misattribute `actions` to `zimmSubscribeModal.css.ts`, which
    42	 * correctly does not declare it.
    43	 */
    44	import { describe, expect, test } from 'vitest';
    45	import { existsSync, readFileSync, readdirSync } from 'node:fs';
    46	import path from 'node:path';
    47	
    48	const COMPONENTS = path.resolve(process.cwd(), 'overrides/app/components');
    49	
    50	const walk = (dir: string): string[] =>
    51	  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    52	    const full = path.join(dir, entry.name);
    53	    return entry.isDirectory() ? walk(full) : [full];
    54	  });
    55	
    56	/** `parts: ['root', 'label']` — the literal array in a `.css.ts` recipe. */
    57	const PARTS_RE = /\bparts:\s*\[([^\]]*)\]/;
    58	/** `styles.label` and `styles['label']`, the two ways a component reads a resolved part. */
    59	const READ_RE = /\bstyles(?:\.([A-Za-z][A-Za-z0-9]*)|\[\s*'([^']+)'\s*\])/g;
    60	
    61	type MultipartRecipe = {
    62	  name: string;
    63	  recipeFile: string;
    64	  componentFile: string;
    65	  declared: string[];
    66	  read: string[];
    67	  /**
    68	   * Whether the sibling component was found. Recorded rather than thrown on: reading a missing
    69	   * file here would fail *collection*, and vitest reports that as one error for the whole file
    70	   * — taking the vacuity guard below down with it. A guard that disappears when its own
    71	   * assumption breaks is the exact failure this suite exists to prevent.
    72	   */
    73	  componentFound: boolean;
    74	};
    75	
    76	const collectMultipartRecipes = (): MultipartRecipe[] =>
    77	  walk(COMPONENTS)
    78	    .filter((file) => file.endsWith('.css.ts'))
    79	    .flatMap((recipeFile) => {
    80	      const declaredMatch = PARTS_RE.exec(readFileSync(recipeFile, 'utf8'));
    81	      if (!declaredMatch) return []; // single-part recipe — nothing to reconcile
    82	
    83	      const declared = declaredMatch[1]
    84	        .split(',')
    85	        .map((entry) => entry.trim().replace(/^['"]|['"]$/g, ''))
    86	        .filter(Boolean);
    87	
    88	      const componentFile = path.join(path.dirname(recipeFile), 'index.tsx');
    89	      const componentFound = existsSync(componentFile);
    90	      const read = componentFound
    91	        ? [...readFileSync(componentFile, 'utf8').matchAll(READ_RE)].map((match) => match[1] ?? match[2])
    92	        : [];
    93	
    94	      return [
    95	        { name: path.basename(recipeFile, '.css.ts'), recipeFile, componentFile, declared, read, componentFound },
    96	      ];
    97	    });
    98	
    99	const recipes = collectMultipartRecipes();
   100	
   101	describe('multipart recipes declare every part their component reads', () => {
   102	  test.each(recipes.map((recipe) => [recipe.name, recipe] as const))('%s', (_name, recipe) => {
   103	    expect(recipe.componentFound, `no component found at ${recipe.componentFile} for ${recipe.recipeFile}`).toBe(true);
   104	    const undeclared = [...new Set(recipe.read)].filter((part) => !recipe.declared.includes(part));
   105	    expect(undeclared, `${recipe.componentFile} reads parts absent from ${recipe.recipeFile}`).toEqual([]);
   106	  });
   107	
   108	  // Vacuity guard. A suite built by walking the filesystem passes trivially when the walk
   109	  // returns nothing — a moved directory or a renamed suffix would turn this file into a
   110	  // no-op that still reports green. Mirrors recipeGuards.test.ts's own self-test.
   111	  test('the walk actually collected something', () => {
   112	    expect(walk(COMPONENTS).length).toBeGreaterThan(0);
   113	    expect(recipes.length).toBeGreaterThan(0);
   114	    expect(recipes.every((recipe) => recipe.declared.length > 0)).toBe(true);
   115	    expect(recipes.some((recipe) => recipe.read.length > 0)).toBe(true);
   116	  });
   117	});
