node -e '
const {existsSync,readFileSync,readdirSync}=require("node:fs");const path=require("node:path");
const COMPONENTS=path.resolve(process.cwd(),"overrides/app/components");
const walk=d=>readdirSync(d,{withFileTypes:true}).flatMap(e=>{const f=path.join(d,e.name);return e.isDirectory()?walk(f):[f]});
const PARTS_RE=/\bparts:\s*\[([^\]]*)\]/;
const READ_RE=/\bstyles(?:\.([A-Za-z][A-Za-z0-9]*)|\[\s*.([^\x27]+).\s*\])/g;
const all=walk(COMPONENTS).filter(f=>f.endsWith(".css.ts"));
console.log("total .css.ts files:",all.length);
const rec=all.flatMap(rf=>{const m=PARTS_RE.exec(readFileSync(rf,"utf8"));if(!m)return[];
const declared=m[1].split(",").map(s=>s.trim().replace(/^[\x27\x22]|[\x27\x22]$/g,"")).filter(Boolean);
const cf=path.join(path.dirname(rf),"index.tsx");const found=existsSync(cf);
const read=found?[...readFileSync(cf,"utf8").matchAll(READ_RE)].map(x=>x[1]??x[2]):[];
return[{name:path.basename(rf,".css.ts"),declared,read:[...new Set(read)],found}]});
console.log("multipart recipes collected:",rec.length);
for(const r of rec) console.log(`  ${r.found?"ok ":"MISS"} ${r.name.padEnd(26)} declared=[${r.declared}] read=[${r.read}] ${r.read.length===0?"  <-- VACUOUS (read is empty)":""}`);
console.log("single-part .css.ts (NOT covered by this guard):");
for(const f of all){if(!PARTS_RE.exec(readFileSync(f,"utf8")))console.log("   ",path.basename(f));}
'

